/**
 * Structured gaps derived from ONE live run's own fields (contexts, polarities, species, disputes, failed searches).
 * Nothing here is generated by a model and nothing is a finding. Each gap says what it is, why the run shows it, and names
 * the candidates and sources behind it. Three scopes are kept apart: scientific (something the evidence shows), retrieval
 * (a limit of this search), and assessment (a check that did not run). Retrieval and assessment gaps are NOT scientific gaps.
 */
import type {LiveInvestigation} from "./liveRun";
export type RunGapKind="context_direction_conflict"|"disputed_claims"|"no_human_source"|"no_candidates"|"no_opposing_found"|"search_failed"|"assessment_not_run";
export type RunGapScope="scientific"|"retrieval"|"assessment";
export type RunGap={id:string;kind:RunGapKind;scope:RunGapScope;title:string;detail:string;contexts:string[];candidateIds:string[];sourceIds:string[];nextStep:string};
const SCOPE:Record<RunGapKind,RunGapScope>={context_direction_conflict:"scientific",disputed_claims:"scientific",no_human_source:"scientific",no_candidates:"retrieval",no_opposing_found:"retrieval",search_failed:"retrieval",assessment_not_run:"assessment"};
const ORDER:RunGapKind[]=["context_direction_conflict","disputed_claims","no_human_source","no_candidates","no_opposing_found","search_failed","assessment_not_run"];
const uniq=<T,>(a:T[])=>[...new Set(a)];
type Run=Pick<LiveInvestigation,"scenarioId"|"byContext"|"candidates"|"searches"|"verification">;

export function deriveRunGaps(run:Run):RunGap[]{
 const out:RunGap[]=[],assessed=run.verification.status!=="not_configured";
 const mk=(kind:RunGapKind,key:string,title:string,detail:string,cands:string[],nextStep:string,contexts:string[]=[])=>{
  const sources=uniq(run.candidates.filter(c=>cands.includes(c.id)).map(c=>c.sourceId));
  out.push({id:`rg:${run.scenarioId}:${kind}:${key}`,kind,scope:SCOPE[kind],title,detail,contexts,candidateIds:cands,sourceIds:sources,nextStep});
 };
 const ctx=Object.entries(run.byContext);
 const label=(k:string)=>run.byContext[k]?.label??k;
 if(assessed){
  const sup=ctx.filter(([,b])=>b.supporting.length>0&&b.opposing.length===0),opp=ctx.filter(([,b])=>b.opposing.length>0&&b.supporting.length===0);
  for(const [ka,a] of sup)for(const [kb,b] of opp)mk("context_direction_conflict",ka+"+"+kb,
   `Direction differs between ${a.label} and ${b.label}`,
   `Checked findings in ${a.label} point one way (${a.supporting.length} supporting, none opposing) and in ${b.label} the other (${b.opposing.length} opposing, none supporting). This may reflect different tissue, cell state, species or assay rather than disagreement.`,
   [...a.supporting,...b.opposing],"Compare tissue, cell state, species, assay and timing in the cited sentences before treating these as contradictory.",[ka,kb]);
  const disputed=run.candidates.filter(c=>c.verification==="disputed");
  if(disputed.length>0)mk("disputed_claims","all",`${disputed.length} claim${disputed.length===1?"":"s"} the two checks disagreed on`,
   "The two model checks gave different directions for these sentences, so their direction is unresolved. Disagreement between checks is not evidence for either direction.",
   disputed.map(c=>c.id),"Read the source passages; a person should decide which direction the text supports.",uniq(disputed.flatMap(c=>c.contexts)));
 }
 for(const [k,b] of ctx){
  const cs=run.candidates.filter(c=>c.contexts.includes(k));
  if(cs.length===0)mk("no_candidates",k,`No candidate sentence found for ${b.label}`,`The retrieved abstracts for ${b.label} produced no candidate sentence. This is a limit of this retrieval, not a finding.`,[],"Widen the search terms or add full-text sources; abstract-only retrieval can miss relevant studies.",[k]);
  else{
   if(!cs.some(c=>c.species==="human"))mk("no_human_source",k,`No candidate for ${b.label} states a human source`,`None of the ${cs.length} candidate${cs.length===1?"":"s"} for ${b.label} names patients or humans in the sentence. Species is read from the sentence by pattern, so this can also mean it was not stated.`,cs.map(c=>c.id),"Look for human studies, or confirm the species in the full text of the cited sources.",[k]);
   if(assessed&&b.opposing.length===0)mk("no_opposing_found",k,`No opposing finding identified for ${b.label}`,`No checked candidate for ${b.label} was assessed as opposing. This does not establish consensus; a dedicated search for opposing evidence was not run.`,[],"Search specifically for null or opposite results in this context.",[k]);
  }
 }
 for(const s of run.searches.filter(x=>x.status==="failed"))mk("search_failed",s.provider+":"+s.context,`Search failed: ${s.provider} for ${label(s.context)}`,`${s.provider} did not return results for ${label(s.context)} (${s.error}). Absence of results there is not evidence of absence.`,[],"Re-run the investigation or query that source directly.",[s.context]);
 if(!assessed)mk("assessment_not_run","verification","Claim directions were not assessed",run.verification.reason??"The two-model check did not run on this deployment, so no claim direction is assessed and conflicts between contexts cannot be detected.",[],"Enable the model check, or read the candidate sentences directly.");
 return out.sort((a,b)=>ORDER.indexOf(a.kind)-ORDER.indexOf(b.kind)||a.id.localeCompare(b.id));
}
